355	 * The failing BDD step reads it back. Revert with the step-side instrumentation once confirmed.
356	 */
357	const recordCancelDiag = (editor: PlateEditor, pending: PendingAuthoring): void => {
358	  if (typeof document === "undefined") return;
359	  const w = window as unknown as { __diag?: unknown[] };
360	  const log = (w.__diag ??= []);
361	  const active = document.activeElement;
362	  log.push({
363	    ev: "cancel",
364	    id: pending.applied.id,
365	    modelClean: !hasAnnotationMark(editor, pending.kind, pending.applied.id),
366	    domCount: document.querySelectorAll(`[data-testid="annotation-${pending.kind}"]`).length,
367	    activeTag: active ? active.tagName : null,
368	  });
