371	/**
372	 * Own the inline composer's `pending` state and its save / cancel handlers.
373	 *
374	 * The eager "Pattern A" mark is rolled back **synchronously inside the cancel
375	 * event**, before the close commits and Radix's modal focus-restoration runs.
376	 * A deferred rollback (post-commit effect) races that focus restoration on the
377	 * overlay-dismiss route under CI load and intermittently leaves the highlight
378	 * behind (symbiot#231); running it in the handler closes the race.
379	 *
380	 * Save and cancel are already separate handlers: a save closes the dialog
381	 * programmatically (`open` → false), which does NOT fire Radix `onOpenChange`,
382	 * so it never reaches {@link onComposerCancel}; only genuine dismisses (button /
383	 * Escape / overlay click) do. `savedRef` still guards the rollback so that even
384	 * if a controlled close were to surface through `onOpenChange`, a just-saved mark
385	 * is kept; it is cleared whenever a fresh composer opens so a prior save never
386	 * suppresses the next cancel. `pendingRef` mirrors `pending` so the handler rolls
387	 * back the CURRENT id even when Radix invokes the callback from a stale render.
388	 * Extracted (like {@link useRemoveAnnotation}) so `ReviewEditor` stays under the
389	 * per-function line cap.
390	 */
391	export const useComposerController = (
392	  editor: PlateEditor,
393	  maps: AnnotationMaps,
394	  setters: PruneSetters,
395	  onChange?: (snapshot: EditorSnapshot) => void
396	): ComposerController => {
397	  const [pending, setPending] = useState<PendingAuthoring | null>(null);
398	  const pendingRef = useRef<PendingAuthoring | null>(null);
399	  const savedRef = useRef(false);
400	
401	  useEffect(() => {
402	    pendingRef.current = pending;
403	    if (pending !== null) savedRef.current = false;
404	  }, [pending]);
405	
406	  const onComposerSave = useCallback(
407	    (payload: AnnotationComposerPayload): void => {
408	      const { current } = pendingRef;
409	      if (current === null) return;
410	      dispatchComposerSave(current, payload, setters);
411	      savedRef.current = true;
412	      setPending(null);
413	    },
414	    [setters]
415	  );
416	
417	  const onComposerCancel = useCallback((): void => {
418	    if (savedRef.current) {
419	      savedRef.current = false;
420	      return;
421	    }
422	    const { current } = pendingRef;
423	    if (current === null) {
424	      setPending(null);
425	      return;
426	    }
427	    // Close the composer and roll the eager mark back in one synchronous commit. A React
428	    // re-render/remount does NOT clear the highlight on the blurred overlay-dismiss route
429	    // (symbiot#231 __diag: modelClean=true, domCount=1, editor blurred) — slate-react won't
430	    // reconcile the cleaned value into the blurred editor's DOM. Replacing the value with a
431	    // fresh array forces it to rebuild every leaf from the already-cleaned children.
432	    // eslint-disable-next-line @eslint-react/dom-no-flush-sync, n/no-sync -- synchronous commit before Radix focus restoration (symbiot#231)
433	    flushSync(() => {
434	      setPending(null);
435	      dispatchComposerCancel(current, editor, maps, onChange);
436	      editor.tf.setValue([...editor.children]);
437	    });
438	    recordCancelDiag(editor, current);
439	  }, [editor, maps, onChange]);
440	
441	  return { pending, setPending, onComposerSave, onComposerCancel };
442	};
