const surface = kindSurface[kind];
const onOpenChange = useCallback(
  (next: boolean): void => {
    // Overlay-dismiss is the ONLY cancel route that reaches onCancel from Radix's native
    // pointerdown listener; the Cancel button and Escape run onCancel inside React synthetic
    // events via ComposerForm. Rolling the eager highlight back synchronously inside that
    // native event leaves slate-react unreconciled on the blurred, read-only editor, so the
    // mark survives under CI load (symbiot#236). Deferring to a microtask runs the identical
    // rollback after the native handler unwinds — the same out-of-native-event context the
    // working routes already use — which is the isolated differentiator the RCA pinned down.
    if (!next) queueMicrotask(onCancel);
  },
  [onCancel]
);

